    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Missing TPT screening and plan",
    "message": "Guidelines recommend initiating TB preventive treatment (TPT) after 3 months on ART for newly initiating patients. Patient started ART 10 weeks ago and will reach the 3-month threshold soon. No TB screening or TPT plan is documented. TB screening is especially important in pregnancy given increased vulnerability. No TB symptoms are reported, which would support TPT eligibility once the 3-month mark is reached. The clinician should assess TB status and plan TPT initiation at the next visit.",
    "issue_type": "plan_add",
